+// Shared in-memory store for items.
+// Items are kept in creation order; ids are i1, i2, i3, ...
+const store = new Map();      // item_id -> item object
+const order = [];             // item_ids in creation order
+let counter = 0;
+
+// Known string fields carried by an item.
+const ITEM_FIELDS = ['name', 'tag', 'description'];
+
+function isString(v) {
+  return typeof v === 'string';
+}
+
+function isNonEmptyString(v) {
+  return isString(v) && v.length > 0;
+}
+
+function fail(message, code = -32602) {
+  const err = new Error(message);
+  err.code = code;
+  return err;
+}
+
+function textResult(obj) {
+  return { content: [{ type: 'text', text: JSON.stringify(obj) }] };
+}
+
+// Validate the string fields of a payload (create/update).
+// `required` fields must be present and non-empty; others, if present,
+// must be strings.
+function validateFields(args, { require = [] } = {}) {
+  for (const field of ITEM_FIELDS) {
+    if (field in args) {
+      if (!isString(args[field])) {
+        throw fail(field + ' must be a string');
+      }
+      if (require.includes(field) && !isNonEmptyString(args[field])) {
+        throw fail(field + ' must be a non-empty string');
+      }
+    } else if (require.includes(field)) {
+      throw fail(field + ' is required');
+    }
+  }
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'item_create',
+      description:
+        'Create a new item in the shared in-memory store. ' +
+        'IDs are assigned as i1, i2, ... in creation order.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          name: { type: 'string', description: 'The name of the item.' },
+          tag: { type: 'string', description: 'An optional tag for the item.' },
+          description: { type: 'string', description: 'An optional description.' },
+        },
+        required: ['name'],
+        additionalProperties: false,
+      },
+    },
+    {
+      name: 'item_update',
+      description:
+        'Update an existing item by id. Only the supplied fields change; ' +
+        'unspecified fields are preserved.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          item_id: { type: 'string', description: 'The id of the item to update.' },
+          name: { type: 'string', description: 'New name value.' },
+          tag: { type: 'string', description: 'New tag value.' },
+          description: { type: 'string', description: 'New description value.' },
+        },
+        required: ['item_id'],
+        additionalProperties: false,
+      },
+    },
+    {
+      name: 'item_get',
+      description: 'Get a single item by id.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          item_id: { type: 'string', description: 'The id of the item to retrieve.' },
+        },
+        required: ['item_id'],
+        additionalProperties: false,
+      },
+    },
+    {
+      name: 'item_list',
+      description: 'List all items in creation order.',
+      inputSchema: {
+        type: 'object',
+        properties: {},
+        required: [],
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  switch (name) {
+    case 'item_create': {
+      validateFields(args, { require: ['name'] });
+      counter += 1;
+      const id = 'i' + counter;
+      const item = { item_id: id };
+      for (const field of ITEM_FIELDS) {
+        if (field in args) item[field] = args[field];
+      }
+      store.set(id, item);
+      order.push(id);
+      return textResult(item);
+    }
+
+    case 'item_update': {
+      if (!isNonEmptyString(args.item_id)) {
+        throw fail('item_id must be a non-empty string');
+      }
+      const item = store.get(args.item_id);
+      if (!item) {
+        throw fail('item not found: ' + args.item_id);
+      }
+      validateFields(args, { require: [] });
+      for (const field of ITEM_FIELDS) {
+        if (field in args) item[field] = args[field];
+      }
+      return textResult(item);
+    }
+
+    case 'item_get': {
+      if (!isNonEmptyString(args.item_id)) {
+        throw fail('item_id must be a non-empty string');
+      }
+      const item = store.get(args.item_id);
+      if (!item) {
+        throw fail('item not found: ' + args.item_id);
+      }
+      return textResult(item);
+    }
+
+    case 'item_list': {
+      return textResult(order.map((id) => store.get(id)));
+    }
+
+    default:
+      throw fail('Unknown tool: ' + name, -32601);
+  }
+}
